def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    opp_budgets = []
    opp_hp = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            opp_budgets.append(opp.get('budget', 0))
            opp_hp.append(opp.get('hp', 0))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    rich_opp = max(opp_budgets) if opp_budgets else 0.0
    weak_opp_count = sum(1 for x in opp_hp if x <= 3)

    tight_supply = supply <= 17
    loose_supply = supply >= 22
    danger = hp <= 3 or no_water_days >= 1
    critical = hp <= 2 or no_water_days >= 2

    if critical:
        bid = max(0.92 * DAILY_SALARY, highest_prev + 2.0)
    elif danger:
        if tight_supply:
            bid = max(0.82 * DAILY_SALARY, highest_prev + 1.5)
        else:
            bid = max(0.72 * DAILY_SALARY, avg_prev + 1.0)
    else:
        if tight_supply:
            bid = max(0.68 * DAILY_SALARY, highest_prev + 1.0)
        elif loose_supply:
            bid = max(0.38 * DAILY_SALARY, avg_prev * 0.72)
        else:
            bid = max(0.52 * DAILY_SALARY, avg_prev * 0.9)

    if highest_prev >= 135:
        if not danger:
            bid = min(bid, 0.62 * DAILY_SALARY)
        else:
            bid = max(bid, 0.86 * DAILY_SALARY)

    if rich_opp < 120 and day >= 6:
        bid *= 0.9
    if weak_opp_count >= 2 and day >= 5:
        bid *= 0.92
    if day >= 8 and hp >= 5:
        bid *= 0.94

    min_safe = 12.0 if not danger else 25.0
    bid = max(bid, min_safe)
    bid = min(bid, budget)
    if budget < 20:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    base_bid = DAILY_SALARY * 0.75

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.85

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if my_status['hp'] <= 4 or highest_prev_bid >= DAILY_SALARY * 0.8:
            base_bid = max(base_bid, highest_prev_bid + 5)
        else:
            base_bid = max(base_bid, highest_prev_bid + 2)

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2 and my_status['hp'] <= 4:
        base_bid = max(base_bid, DAILY_SALARY * 0.98)

    final_bid = min(my_status['budget'], base_bid)

    return max(0.1, final_bid)
